files.content:
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #2b233a;
  --card-bg: #453a5c;
  --board-bg: #2d4c38;
  --desk-wood: #c48b4f;
  --desk-wood-dark: #8d5524;
  --desk-empty: #e2ab70;
  --desk-occupied: #5c946e;
  --desk-occupied-dark: #376346;
  --text-main: #f3effa;
  --text-muted: #d0c5e3;
  --accent: #ffd166;
  --focus-ring: #ffea79;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--bg-color);
  font-family: "Courier New", Courier, monospace, system-ui, sans-serif;
  font-size: 16px;
  color: var(--text-main);
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 1rem;
}

.classroom-card {
  background-color: var(--card-bg);
  border: 4px solid #1a1524;
  box-shadow: 0 8px 0 #14101c;
  border-radius: 8px;
  width: 100%;
  max-width: 640px;
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.classroom-header {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  text-align: center;
}

.title {
  font-size: 1.5rem;
  letter-spacing: 2px;
  color: var(--accent);
  text-shadow: 2px 2px 0 #1a1524;
}

.blackboard {
  background-color: var(--board-bg);
  border: 4px solid var(--desk-wood);
  padding: 0.5rem;
  border-radius: 4px;
  box-shadow: inset 0 0 0 2px #1f3627;
}

.chalk-text {
  color: #f7fff7;
  font-size: 0.85rem;
  letter-spacing: 1.5px;
  font-weight: bold;
}

.controls-section {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  background: rgba(0, 0, 0, 0.2);
  padding: 1rem;
  border-radius: 6px;
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.label {
  font-size: 0.95rem;
  font-weight: bold;
  color: var(--text-main);
}

.pixel-input {
  font-family: inherit;
  font-size: 1rem;
  padding: 0.6rem 0.75rem;
  border: 3px solid #1a1524;
  background-color: #f5f1fa;
  color: #1a1524;
  border-radius: 4px;
  box-shadow: inset 2px 2px 0 #b3a5c7;
  outline: none;
}

.pixel-input:focus {
  border-color: var(--focus-ring);
  box-shadow: 0 0 0 3px var(--focus-ring);
}

.hint-text {
  font-size: 0.85rem;
  color: var(--text-muted);
}

.counter-box {
  font-size: 1rem;
  color: var(--accent);
  padding-top: 0.25rem;
}

.seating-area {
  display: flex;
  justify-content: center;
}

.desk-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-template-rows: repeat(3, auto);
  gap: 0.75rem;
  width: 100%;
}

.desk-cell {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 84px;
  background-color: var(--desk-empty);
  border: 3px solid var(--desk-wood-dark);
  box-shadow: 0 4px 0 var(--desk-wood-dark);
  border-radius: 6px;
  cursor: pointer;
  color: #3b2209;
  font-family: inherit;
  padding: 0.4rem;
  text-align: center;
  transition: transform 0.05s ease, background-color 0.15s ease;
  outline: none;
}

.desk-cell:hover {
  filter: brightness(1.08);
  transform: translateY(-2px);
  box-shadow: 0 6px 0 var(--desk-wood-dark);
}

.desk-cell:active {
  transform: translateY(2px);
  box-shadow: 0 2px 0 var(--desk-wood-dark);
}

.desk-cell:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
}

.desk-cell.occupied {
  background-color: var(--desk-occupied);
  border-color: var(--desk-occupied-dark);
  box-shadow: 0 4px 0 var(--desk-occupied-dark);
  color: #ffffff;
}

.desk-cell.occupied:hover {
  box-shadow: 0 6px 0 var(--desk-occupied-dark);
}

.desk-cell.occupied:active {
  box-shadow: 0 2px 0 var(--desk-occupied-dark);
}

.desk-status {
  font-size: 0.75rem;
  font-weight: bold;
  opacity: 0.85;
  text-transform: uppercase;
}

.student-name {
  font-size: 0.95rem;
  font-weight: bold;
  margin-top: 0.25rem;
  word-break: break-word;
  max-width: 100%;
}

@media (max-width: 480px) {
  .desk-grid {
    gap: 0.5rem;
  }

  .desk-cell {
    min-height: 72px;
    padding: 0.25rem;
  }

  .student-name {
    font-size: 0.8rem;
  }

  .title {
    font-size: 1.25rem;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const TOTAL_ROWS = 3;
  const TOTAL_COLS = 4;
  const TOTAL_DESKS = TOTAL_ROWS * TOTAL_COLS;

  const desks = Array.from({ length: TOTAL_DESKS }, (_, i) => ({
    id: i,
    row: Math.floor(i / TOTAL_COLS) + 1,
    col: (i % TOTAL_COLS) + 1,
    student: null
  }));

  const nameInput = document.getElementById('student-name-input');
  const deskGrid = document.getElementById('desk-grid');
  const counterDisplay = document.getElementById('counter-display');
  const instructionText = document.getElementById('instruction-text');

  function updateCounter() {
    const filledCount = desks.filter(d => d.student !== null).length;
    counterDisplay.textContent = `${filledCount} / ${TOTAL_DESKS}`;
  }

  function renderDesk(desk, element) {
    element.innerHTML = '';
    if (desk.student) {
      element.classList.add('occupied');
      element.setAttribute('aria-label', `Row ${desk.row}, Column ${desk.col}: Occupied by ${desk.student}. Click to clear seat.`);

      const statusSpan = document.createElement('span');
      statusSpan.className = 'desk-status';
      statusSpan.textContent = 'Seated';

      const nameSpan = document.createElement('span');
      nameSpan.className = 'student-name';
      nameSpan.textContent = desk.student;

      element.appendChild(statusSpan);
      element.appendChild(nameSpan);
    } else {
      element.classList.remove('occupied');
      element.setAttribute('aria-label', `Row ${desk.row}, Column ${desk.col}: Empty desk. Click to seat student.`);

      const emptySpan = document.createElement('span');
      emptySpan.className = 'desk-status';
      emptySpan.textContent = '[Empty]';
      element.appendChild(emptySpan);
    }
  }

  function handleDeskClick(index, deskButton) {
    const desk = desks[index];

    if (desk.student !== null) {
      desk.student = null;
      renderDesk(desk, deskButton);
      updateCounter();
      instructionText.textContent = `Cleared Row ${desk.row}, Column ${desk.col}.`;
      return;
    }

    const name = nameInput.value.trim();
    if (!name) {
      instructionText.textContent = 'Please enter a student name first!';
      nameInput.focus();
      return;
    }

    desk.student = name;
    renderDesk(desk, deskButton);
    updateCounter();
    instructionText.textContent = `Seated ${name} at Row ${desk.row}, Column ${desk.col}.`;
    nameInput.value = '';
    nameInput.focus();
  }

  function initGrid() {
    deskGrid.innerHTML = '';
    desks.forEach((desk, idx) => {
      const deskButton = document.createElement('button');
      deskButton.type = 'button';
      deskButton.className = 'desk-cell';
      deskButton.dataset.index = idx;
      renderDesk(desk, deskButton);

      deskButton.addEventListener('click', () => handleDeskClick(idx, deskButton));
      deskGrid.appendChild(deskButton);
    });
    updateCounter();
  }

  nameInput.addEventListener('keydown', (event) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      const firstEmptyIndex = desks.findIndex(d => d.student === null);
      if (firstEmptyIndex !== -1) {
        const button = deskGrid.children[firstEmptyIndex];
        if (button) {
          handleDeskClick(firstEmptyIndex, button);
        }
      } else {
        instructionText.textContent = 'All desks are full! Click a desk to clear it first.';
      }
    }
  });

  initGrid();
});
